package ir.alirezaivaz.mygarage;
import android.app.Activity;import android.content.Intent;import android.content.SharedPreferences;import android.database.Cursor;import android.net.Uri;import android.os.Bundle;import android.graphics.Color;import android.provider.OpenableColumns;import android.webkit.JavascriptInterface;import android.webkit.WebChromeClient;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;import android.webkit.WebResourceRequest;import android.view.Window;import android.view.WindowManager;import android.widget.FrameLayout;import androidx.core.view.ViewCompat;import androidx.core.view.WindowCompat;import androidx.core.view.WindowInsetsCompat;import org.json.JSONObject;import java.io.ByteArrayOutputStream;import java.io.InputStream;import java.io.OutputStream;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity{
private static final int REQUEST_EXPORT=4101,REQUEST_IMPORT=4102,REQUEST_DRIVE_CONNECT=4103,REQUEST_DRIVE_RESTORE=4104,MAX_BACKUP_BYTES=10*1024*1024;private static final String PREFS="mygarage_drive",PREF_URI="backup_uri",PREF_NAME="backup_name",PREF_SYNC="last_sync";private WebView web;private String pendingBackupJson,pendingDriveJson;
public final class BackBridge{@JavascriptInterface public void exit(){runOnUiThread(MainActivity.this::finish);}}
public final class BackupBridge{
@JavascriptInterface public void exportBackup(String json){if(!valid(json)){notifyJs("onBackupSaved(false)");return;}runOnUiThread(()->{pendingBackupJson=json;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"my-car-service-backup.json");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(i,REQUEST_EXPORT);}catch(Exception e){pendingBackupJson=null;notifyJs("onBackupSaved(false)");}});}
@JavascriptInterface public void importBackup(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(i,REQUEST_IMPORT);}catch(Exception e){notifyJs("onBackupFailed("+JSONObject.quote("انتخاب فایل در دسترس نیست.")+")");}});}
@JavascriptInterface public void connectDrive(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"MyGarage-Backup.json");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(i,REQUEST_DRIVE_CONNECT);}catch(Exception e){notifyJs("onDriveConnected(false,'',"+JSONObject.quote("انتخاب محل ذخیره‌سازی در دسترس نیست.")+")");}});}
@JavascriptInterface public void syncDrive(String json){if(!valid(json)){notifyJs("onDriveSyncResult(false,'',"+JSONObject.quote("فایل پشتیبان نامعتبر یا بزرگ‌تر از ۱۰ مگابایت است.")+")");return;}runOnUiThread(()->{String saved=prefs().getString(PREF_URI,null);if(saved==null){pendingDriveJson=json;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"MyGarage-Backup.json");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(i,REQUEST_DRIVE_CONNECT);}catch(Exception e){pendingDriveJson=null;notifyJs("onDriveSyncResult(false,'',"+JSONObject.quote("اتصال به فضای ذخیره‌سازی انجام نشد.")+")");}}else writeDrive(Uri.parse(saved),json);});}
@JavascriptInterface public void restoreDrive(){runOnUiThread(()->{String saved=prefs().getString(PREF_URI,null);if(saved!=null){readDrive(Uri.parse(saved));return;}Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(i,REQUEST_DRIVE_RESTORE);}catch(Exception e){notifyJs("onDriveRestoreResult(false,"+JSONObject.quote("انتخاب فایل از Drive ممکن نشد.")+")");}});}
@JavascriptInterface public void getDriveStatus(){SharedPreferences p=prefs();notifyJs("onDriveStatus("+(p.getString(PREF_URI,null)!=null)+","+JSONObject.quote(p.getString(PREF_NAME,""))+","+JSONObject.quote(p.getString(PREF_SYNC,""))+")");}}
private boolean valid(String s){return s!=null&&s.getBytes(StandardCharsets.UTF_8).length<=MAX_BACKUP_BYTES;}private SharedPreferences prefs(){return getSharedPreferences(PREFS,MODE_PRIVATE);}
private String name(Uri u){try(Cursor c=getContentResolver().query(u,null,null,null,null)){if(c!=null&&c.moveToFirst()){int n=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(n>=0)return c.getString(n);}}catch(Exception ignored){}return "MyGarage-Backup.json";}
private void keep(Uri u,Intent d,boolean write){try{int f=d.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if(write)f|=Intent.FLAG_GRANT_WRITE_URI_PERMISSION;getContentResolver().takePersistableUriPermission(u,f);}catch(Exception ignored){}prefs().edit().putString(PREF_URI,u.toString()).putString(PREF_NAME,name(u)).apply();}
private void writeDrive(Uri u,String json){new Thread(()->{boolean ok=false;String error="",stamp=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",java.util.Locale.US).format(new java.util.Date());try(OutputStream o=getContentResolver().openOutputStream(u,"wt")){if(o==null)throw new IllegalStateException("فایل Drive قابل نوشتن نیست.");o.write(json.getBytes(StandardCharsets.UTF_8));o.flush();prefs().edit().putString(PREF_SYNC,stamp).apply();ok=true;}catch(Exception e){error=e.getMessage()==null?"ذخیره در Drive ناموفق بود.":e.getMessage();}final boolean success=ok;final String msg=error;runOnUiThread(()->notifyJs("onDriveSyncResult("+success+","+JSONObject.quote(success?stamp:prefs().getString(PREF_SYNC,""))+","+JSONObject.quote(msg)+")"));}).start();}
private void readDrive(Uri u){new Thread(()->{String json=null,error="";try(InputStream in=getContentResolver().openInputStream(u);ByteArrayOutputStream b=new ByteArrayOutputStream()){if(in==null)throw new IllegalStateException("فایل Drive قابل خواندن نیست.");byte[] x=new byte[8192];int n,total=0;while((n=in.read(x))!=-1){total+=n;if(total>MAX_BACKUP_BYTES)throw new IllegalStateException("حجم فایل بیشتر از ۱۰ مگابایت است.");b.write(x,0,n);}json=b.toString(StandardCharsets.UTF_8.name());}catch(Exception e){error=e.getMessage()==null?"خواندن از Drive ناموفق بود.":e.getMessage();}final String content=json,msg=error;runOnUiThread(()->{if(content!=null){notifyJs("onDriveRestoreResult(true,'')");notifyJs("onBackupLoaded("+JSONObject.quote(content)+")");}else notifyJs("onDriveRestoreResult(false,"+JSONObject.quote(msg)+")");});}).start();}
@Override protected void onCreate(Bundle b){super.onCreate(b);Window w=getWindow();w.setStatusBarColor(Color.rgb(11,20,32));w.setNavigationBarColor(Color.rgb(11,20,32));w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);if(android.os.Build.VERSION.SDK_INT>=29){w.setNavigationBarContrastEnforced(false);w.setStatusBarContrastEnforced(false);}WindowCompat.setDecorFitsSystemWindows(w,false);FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(11,20,32));web=new WebView(this);web.setBackgroundColor(Color.rgb(11,20,32));web.setOverScrollMode(WebView.OVER_SCROLL_NEVER);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(false);s.setAllowFileAccess(true);s.setAllowContentAccess(false);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);s.setSupportZoom(false);s.setBuiltInZoomControls(false);s.setDisplayZoomControls(false);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);if(android.os.Build.VERSION.SDK_INT>=26)s.setSafeBrowsingEnabled(true);web.addJavascriptInterface(new BackBridge(),"AndroidBack");web.addJavascriptInterface(new BackupBridge(),"AndroidFiles");web.setWebChromeClient(new WebChromeClient());web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("file:///android_asset/");}});root.addView(web,new FrameLayout.LayoutParams(-1,-1));ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{androidx.core.graphics.Insets bars=insets.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());web.setPadding(0,bars.top,0,bars.bottom);return insets;});setContentView(root);ViewCompat.requestApplyInsets(root);web.loadUrl("file:///android_asset/index.html");}
private void notifyJs(String js){runOnUiThread(()->{if(web!=null)web.evaluateJavascript(js,null);});}
@Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);
if(req==REQUEST_DRIVE_CONNECT){if(res!=RESULT_OK||data==null||data.getData()==null){pendingDriveJson=null;notifyJs("onDriveConnected(false,'',"+JSONObject.quote("انتخاب فایل لغو شد.")+")");return;}Uri u=data.getData();keep(u,data,true);notifyJs("onDriveConnected(true,"+JSONObject.quote(prefs().getString(PREF_NAME,""))+",'')");String p=pendingDriveJson;pendingDriveJson=null;if(p!=null)writeDrive(u,p);return;}
if(req==REQUEST_DRIVE_RESTORE){if(res!=RESULT_OK||data==null||data.getData()==null){notifyJs("onDriveRestoreResult(false,"+JSONObject.quote("انتخاب فایل لغو شد.")+")");return;}Uri u=data.getData();keep(u,data,true);readDrive(u);return;}
if(res!=RESULT_OK||data==null||data.getData()==null){if(req==REQUEST_EXPORT){pendingBackupJson=null;notifyJs("onBackupSaved(false)");}return;}Uri u=data.getData();
if(req==REQUEST_EXPORT){String json=pendingBackupJson;pendingBackupJson=null;try(OutputStream o=getContentResolver().openOutputStream(u)){if(o==null||json==null)throw new IllegalStateException();o.write(json.getBytes(StandardCharsets.UTF_8));o.flush();notifyJs("onBackupSaved(true)");}catch(Exception e){notifyJs("onBackupSaved(false)");}}
else if(req==REQUEST_IMPORT){try(InputStream in=getContentResolver().openInputStream(u);ByteArrayOutputStream b=new ByteArrayOutputStream()){if(in==null)throw new IllegalStateException("فایل خوانده نشد.");byte[] x=new byte[8192];int n,total=0;while((n=in.read(x))!=-1){total+=n;if(total>MAX_BACKUP_BYTES)throw new IllegalStateException("حجم فایل بیشتر از ۱۰ مگابایت است.");b.write(x,0,n);}notifyJs("onBackupLoaded("+JSONObject.quote(b.toString(StandardCharsets.UTF_8.name()))+")");}catch(Exception e){notifyJs("onBackupFailed("+JSONObject.quote(e.getMessage()==null?"خواندن فایل ناموفق بود.":e.getMessage())+")");}}}
@Override public void onBackPressed(){if(web==null){super.onBackPressed();return;}web.evaluateJavascript("if(document.querySelector('.modal-back')){closeModal();}else if(!document.getElementById('drawerOverlay').classList.contains('hidden')){closeDrawer();}else if(document.body.dataset.page!=='home'){showPage('home');}else{AndroidBack.exit();}",null);}
@Override protected void onDestroy(){if(web!=null){web.removeJavascriptInterface("AndroidBack");web.removeJavascriptInterface("AndroidFiles");web.stopLoading();web.loadUrl("about:blank");web.destroy();web=null;}super.onDestroy();}
}